<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, Plus } from '@element-plus/icons-vue'
import { getDishList } from '../../api/user/dishes'
import { getComboList } from '../../api/user/combos'
import { addToCart } from '../../api/user/cart'
import { ElMessage } from 'element-plus'
import { resolveFileUrl } from '../../utils/fileUrl'

const router = useRouter()
const loading = ref(false)
const dishes = ref<any[]>([])
const combos = ref<any[]>([])
const fallback = ['/images/home/salad-card.jpg', '/images/home/meal-card.jpg', '/images/home/hero-fresh-bowl.jpg']
const featured = computed(() => dishes.value.slice(0, 3))
const imageFor = (item: any, index: number, field: string) => resolveFileUrl(item[field]) || fallback[index % fallback.length]

const load = async () => {
  loading.value = true
  try {
    const [dishRes, comboRes] = await Promise.all([getDishList({ page: 1, size: 6 }), getComboList({ page: 1, size: 3 })])
    dishes.value = dishRes.data?.data?.list || []
    combos.value = comboRes.data?.data?.list || []
  } catch {
    ElMessage.error('加载首页内容失败')
  } finally { loading.value = false }
}

const add = async (dish: any) => {
  try { await addToCart(10, dish.id, undefined, 1); ElMessage.success('已加入购物车') }
  catch { ElMessage.error('加入购物车失败') }
}
onMounted(load)
</script>

<template>
  <div class="home">
    <section class="hero">
      <div class="hero-copy">
        <span class="section-index">01 / 今日饮食</span>
        <h1>今天，<br />吃得刚刚好。</h1>
        <p>按你的目标，安排下一顿。</p>
        <div class="hero-actions">
          <el-button type="primary" size="large" @click="router.push('/user/ai/recommend')">生成今日食谱</el-button>
        </div>
        <div class="hero-meta"><span><b>12+</b> 营养搭配方案</span><span><b>30 min</b> 新鲜配送准备</span></div>
      </div>
      <div class="hero-media">
        <img src="/images/home/hero-fresh-bowl.jpg" alt="新鲜健康食材" />
        <div class="media-label"><span>新鲜 · 均衡 · 为你定制</span><strong>今日餐桌</strong></div>
      </div>
    </section>

    <section class="daily-line">
      <span class="daily-title">今天从一顿好饭开始</span>
      <i class="daily-rule"></i>
      <p>记录饮食 · 生成食谱 · 选择套餐 · 配送到家</p>
      <button @click="router.push('/user/profile')">完善健康档案 <ArrowRight /></button>
    </section>

    <section class="menu-section">
      <div class="section-heading"><div><span class="section-index">02 / 精选菜单</span><h2>不必将就的一份好餐</h2></div><button @click="router.push('/user/dishes')">全部菜品 <ArrowRight /></button></div>
      <div class="menu-layout" :class="{ 'is-empty': !loading && !featured.length, 'is-loading': loading }">
        <article v-for="(dish, index) in featured" :key="dish.id" class="menu-item" :class="`item-${index}`">
          <img :src="imageFor(dish, index, 'dishImage')" :alt="dish.dishName" />
          <div class="menu-item-copy"><div class="dish-kicker">{{ dish.calories || 0 }} kcal · 蛋白质 {{ dish.protein || 0 }}g</div><div class="dish-title-line"><h3>{{ dish.dishName }}</h3><strong>¥{{ dish.price }}</strong></div><p>{{ dish.description || '新鲜食材搭配，轻松吃得更均衡。' }}</p><button title="加入购物车" @click="add(dish)"><Plus /></button></div>
        </article>
        <article v-if="loading" class="empty-menu skeleton-menu" aria-label="菜品内容加载中">
          <div class="skeleton-tile skeleton-primary"><i></i><b></b><em></em></div>
          <div class="skeleton-tile"><i></i><b></b></div>
          <div class="skeleton-tile"><i></i><b></b></div>
        </article>
        <article v-else-if="!featured.length" class="no-menu">
          <div class="no-menu-media"><img src="/images/home/salad-card.jpg" alt="新鲜健康餐食" /><i></i></div>
          <div class="no-menu-copy"><span>THIS WEEK</span><h3>暂时没有可展示的菜品</h3><p>新一周菜单正在准备，去全部菜品里看看已有的健康搭配。</p><button @click="router.push('/user/dishes')">浏览全部菜品 <ArrowRight /></button></div>
        </article>
      </div>
    </section>

    <section class="plans-section">
      <div class="plans-copy"><span class="section-index">03 / 健康套餐</span><h2>不用计算，<br />也能吃得刚刚好。</h2><p class="plans-manifesto">营养不是限制，而是更了解自己。</p><div class="plan-principles"><span>高蛋白</span><span>新鲜蔬菜</span><span>均衡碳水</span></div></div>
      <div class="plans-showcase">
        <div class="showcase-image"><img src="/images/home/meal-card.jpg" alt="均衡健康餐食" /><span>按目标搭配</span></div>
        <div class="plans-list">
        <article v-for="(combo, index) in combos" :key="combo.id" class="plan-row" @click="router.push('/user/combos')"><span class="plan-no">0{{ index + 1 }}</span><img :src="imageFor(combo, index + 1, 'comboImage')" :alt="combo.comboName" /><div><h3>{{ combo.comboName }}</h3><p>{{ combo.totalCalories || 0 }} kcal · {{ combo.description || '按目标设计的营养搭配' }}</p></div><strong>¥{{ combo.price }}</strong><ArrowRight class="row-arrow" /></article>
          <div v-if="!loading && !combos.length" class="plan-empty"><span>COMING SOON</span><h3>你的专属套餐正在搭配中</h3><button @click="router.push('/user/profile')">完善健康档案 <ArrowRight /></button></div>
        </div>
      </div>
    </section>
  </div>
</template>

